"use strict";(self.webpackChunkdeosai_book=self.webpackChunkdeosai_book||[]).push([["924"],{5226(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"bookSidebar":[{"type":"link","href":"/book/preface","label":"Preface \u2014 Why This Book Exists","docId":"preface","unlisted":false},{"type":"category","label":"Part One \u2014 Foundations","collapsed":false,"items":[{"type":"link","href":"/book/foundations/workflows-not-tools","label":"Workflows, Not Tools","docId":"foundations/workflows-not-tools","unlisted":false},{"type":"link","href":"/book/foundations/forward-deployment-model","label":"The Forward Deployment Model","docId":"foundations/forward-deployment-model","unlisted":false},{"type":"link","href":"/book/foundations/how-to-use-this-book","label":"How to Use This Book","docId":"foundations/how-to-use-this-book","unlisted":false}],"collapsible":true},{"type":"category","label":"Part Two \u2014 Industries","collapsed":false,"items":[{"type":"link","href":"/book/industries/healthcare","label":"Healthcare","docId":"industries/healthcare","unlisted":false},{"type":"link","href":"/book/industries/education","label":"Education","docId":"industries/education","unlisted":false},{"type":"link","href":"/book/industries/retail-ecommerce","label":"Retail & E-commerce","docId":"industries/retail-ecommerce","unlisted":false},{"type":"link","href":"/book/industries/manufacturing","label":"Manufacturing","docId":"industries/manufacturing","unlisted":false},{"type":"link","href":"/book/industries/logistics-supply-chain","label":"Logistics & Supply Chain","docId":"industries/logistics-supply-chain","unlisted":false},{"type":"link","href":"/book/industries/financial-services","label":"Financial Services","docId":"industries/financial-services","unlisted":false},{"type":"link","href":"/book/industries/government","label":"Government","docId":"industries/government","unlisted":false},{"type":"link","href":"/book/industries/agriculture","label":"Agriculture","docId":"industries/agriculture","unlisted":false},{"type":"link","href":"/book/industries/aviation","label":"Aviation","docId":"industries/aviation","unlisted":false},{"type":"link","href":"/book/industries/airline-ticketing","label":"Airline & Ticketing","docId":"industries/airline-ticketing","unlisted":false},{"type":"link","href":"/book/industries/oil-gas","label":"Oil & Gas","docId":"industries/oil-gas","unlisted":false},{"type":"link","href":"/book/industries/professional-services","label":"Professional Services","docId":"industries/professional-services","unlisted":false},{"type":"link","href":"/book/industries/insurance","label":"Insurance","docId":"industries/insurance","unlisted":false},{"type":"link","href":"/book/industries/legal-services","label":"Legal Services","docId":"industries/legal-services","unlisted":false},{"type":"link","href":"/book/industries/real-estate","label":"Real Estate & Property Management","docId":"industries/real-estate","unlisted":false},{"type":"link","href":"/book/industries/energy-utilities","label":"Energy & Utilities","docId":"industries/energy-utilities","unlisted":false},{"type":"link","href":"/book/industries/hospitality-travel","label":"Hospitality & Travel","docId":"industries/hospitality-travel","unlisted":false},{"type":"link","href":"/book/industries/life-sciences-pharmaceuticals","label":"Life Sciences & Pharmaceuticals","docId":"industries/life-sciences-pharmaceuticals","unlisted":false},{"type":"link","href":"/book/industries/construction-engineering","label":"Construction & Engineering","docId":"industries/construction-engineering","unlisted":false}],"collapsible":true},{"type":"category","label":"Part Three \u2014 Next Steps","collapsed":false,"items":[{"type":"link","href":"/book/next-steps/choosing-your-starting-workflow","label":"Choosing Your Starting Workflow","docId":"next-steps/choosing-your-starting-workflow","unlisted":false},{"type":"link","href":"/book/next-steps/working-with-deosai-labs","label":"Working With DeosAI Labs","docId":"next-steps/working-with-deosai-labs","unlisted":false}],"collapsible":true}]},"docs":{"foundations/forward-deployment-model":{"id":"foundations/forward-deployment-model","title":"The Forward Deployment Model","description":"\\"Forward deployed\\" describes how the work gets done, not just what gets built. It\'s a delivery model borrowed from teams that embed engineers directly inside a customer\'s operations \u2014 rather than shipping a generic product and hoping it fits.","sidebar":"bookSidebar"},"foundations/how-to-use-this-book":{"id":"foundations/how-to-use-this-book","title":"How to Use This Book","description":"Every industry chapter in Part Two follows the same structure, so you can compare across industries or jump straight to your own.","sidebar":"bookSidebar"},"foundations/workflows-not-tools":{"id":"foundations/workflows-not-tools","title":"Workflows, Not Tools","description":"\\"AI isn\'t the hard part. Integration is.\\"","sidebar":"bookSidebar"},"industries/agriculture":{"id":"industries/agriculture","title":"Agriculture","description":"Modern farm and agribusiness operations generate more field, equipment, and market data than any team has time to act on \u2014 the gap isn\'t data collection anymore, it\'s turning that data into a decision before the window to act closes.","sidebar":"bookSidebar"},"industries/aviation":{"id":"industries/aviation","title":"Aviation","description":"Aviation operations run on tight, safety-critical schedules where a single documentation delay or maintenance miss can cascade into hours of disruption \u2014 which is exactly the kind of high-stakes, well-documented workflow forward deployment is built for.","sidebar":"bookSidebar"},"industries/education":{"id":"industries/education","title":"Education","description":"Educators and administrators are stretched across instruction, compliance reporting, and individualized student support \u2014 three demands that rarely get equal attention because the first two crowd out the third.","sidebar":"bookSidebar"},"industries/financial-services":{"id":"industries/financial-services","title":"Financial Services","description":"Financial services workflows are already heavily governed by process and audit trail \u2014 which makes them a strong fit for forward deployment, since the discipline of \\"document every decision\\" that regulation requires is exactly what a well-supervised Digital FTE provides by default.","sidebar":"bookSidebar"},"industries/government":{"id":"industries/government","title":"Government","description":"Public sector organizations often serve the largest volume of repetitive, rules-based case processing of any sector \u2014 permit applications, benefits eligibility, records requests \u2014 under public accountability standards that make transparency non-negotiable.","sidebar":"bookSidebar"},"industries/healthcare":{"id":"industries/healthcare","title":"Healthcare","description":"Clinical staff time is the scarcest resource in most healthcare organizations, and a disproportionate share of it is spent on administrative work that has nothing to do with patient care.","sidebar":"bookSidebar"},"industries/logistics-supply-chain":{"id":"industries/logistics-supply-chain","title":"Logistics & Supply Chain","description":"Logistics runs on documents and exceptions \u2014 bills of lading, customs paperwork, delivery confirmations \u2014 and most delays trace back to someone manually reconciling a mismatch between two systems that should already agree.","sidebar":"bookSidebar"},"industries/manufacturing":{"id":"industries/manufacturing","title":"Manufacturing","description":"Manufacturing operations generate enormous volumes of machine and process data, but most of it is read by nobody until something has already gone wrong.","sidebar":"bookSidebar"},"industries/retail-ecommerce":{"id":"industries/retail-ecommerce","title":"Retail & E-commerce","description":"Retail margins are thin enough that operational friction shows up directly on the P&L \u2014 in returns processing, inventory mismatches, and customer service load that scales linearly with order volume instead of getting more efficient.","sidebar":"bookSidebar"},"next-steps/choosing-your-starting-workflow":{"id":"next-steps/choosing-your-starting-workflow","title":"Choosing Your Starting Workflow","description":"If you read your industry chapter and recognized more than one workflow, that\'s normal \u2014 most operations have several. The mistake to avoid is trying to fix all of them at once.","sidebar":"bookSidebar"},"next-steps/working-with-deosai-labs":{"id":"next-steps/working-with-deosai-labs","title":"Working With DeosAI Labs","description":"DeosAI Labs is a forward deployment agency. We don\'t sell a platform and we don\'t sell a strategy deck \u2014 we embed with your team, build a Digital FTE inside a real workflow, and stay accountable for the outcome.","sidebar":"bookSidebar"},"preface":{"id":"preface","title":"Preface \u2014 Why This Book Exists","description":"Most companies do not have an AI problem. They have a workflow visibility problem.","sidebar":"bookSidebar"}}}}')}}]);